function storageGet(key){return new Promise((resolve=>{const id=Math.random().toString(36).slice(2),onMessage=event=>{event.data&&"storage:get:result"===event.data.type&&event.data.id===id&&(window.removeEventListener("message",onMessage),resolve(event.data.value))};window.addEventListener("message",onMessage),window.parent.postMessage({type:"storage:get",key:key,id:id},"*")}))}function storageSet(key,value){return new Promise((resolve=>{const id=Math.random().toString(36).slice(2),onMessage=event=>{event.data&&"storage:set:done"===event.data.type&&event.data.id===id&&(window.removeEventListener("message",onMessage),resolve())};window.addEventListener("message",onMessage),window.parent.postMessage({type:"storage:set",key:key,value:value,id:id},"*")}))}